Capybara.run_server = true
port = (3100 + ENV['TEST_ENV_NUMBER'].to_i)
Capybara.server_port = port

Capybara.register_server :puma do |app, _port, host|
  require 'puma'
  Puma::Server.new(app).tap do |s|
    s.add_tcp_listener host, port
    puts "Starting Puma on #{host}:#{port}"
  end.run.join
end

Capybara.server_host = "localhost"
Capybara.app_host = "http://localhost:#{port}"

# Override environment variables for parallel tests
ENV['HOST'] = "localhost:#{port}"
ENV['DOMAIN'] = "localhost:#{port}"
ENV['BASE_URL'] = "http://localhost:#{port}"
ENV['BASE_DOMAIN'] = "localhost:#{port}"
# Both regions point at the same Capybara port: the suite emulates a two-region deployment in
# one process by swapping CURRENT_SITE between hops (see cross_site_login_steps.rb). SITES is
# JSON - SiteRegistry parses it, it is never eval'd.
ENV['SITES'] = %({"IN":"http://localhost:#{port}","US":"http://localhost:#{port}"})
ENV['CURRENT_SITE'] ||= 'IN'
# The boot initializer already memoised SITES from .env.test (port 3000); clear it so the
# Capybara port above is what SiteRegistry hands out.
SiteRegistry.reset!

# Update Rails default url options
Rails.application.routes.default_url_options[:host] = ENV['HOST']

# Ensure unique logging per parallel process
if ENV['TEST_ENV_NUMBER'].present?
  log_path = Rails.root.join("log/test_#{ENV['TEST_ENV_NUMBER']}.log")
  Rails.logger = ActiveSupport::Logger.new(log_path)
  Rails.logger.formatter = config.log_formatter if defined?(config) && config.respond_to?(:log_formatter)
  ActiveRecord::Base.logger = Rails.logger
end


# Chromium launch flags that cut each worker's memory footprint. A parallel run
# puts one Rails + Puma + `node run-driver` + a multi-process Chromium in RAM per
# worker; when the box runs out, renderers self-terminate and scenarios fail with
# "Page crashed" / "Target crashed", or the driver stops replying and
# playwright_transport_patch.rb reports it wedged. None of these flags change how
# pages render — they only stop Chromium reaching for memory it can't have here.
CHROMIUM_LOW_MEMORY_ARGS = %w[
  --disable-dev-shm-usage
  --disable-gpu
  --renderer-process-limit=2
].freeze

Capybara.register_driver(:playwright) do |app|
  Capybara::Playwright::Driver.new(app,
                                   browser_type: :chromium,
                                   headless: ENV["BROWSER"].blank?,
                                   playwright_cli_executable_path: 'node_modules/.bin/playwright',
                                   args: CHROMIUM_LOW_MEMORY_ARGS,
                                   screen_size: { width: 1680, height: 1100 },
                                   viewport: { width: 1680, height: 1100 },
                                   default_wait_for_load_state: "domcontentloaded",
                                   navigation_timeout: 60_000)
end

Capybara.default_max_wait_time = 15
Capybara.default_driver = :playwright
Capybara.javascript_driver = :playwright
Capybara.save_path = 'tmp/capybara'

ENV["REGION"] ||= "US"

# Provide base URLs for sync API in test
ENV["SYNC_API_BASE_URL_US"] ||= "https://dev.altconnects.us"
ENV["SYNC_API_BASE_URL_IN"] ||= "https://dev.altconnects.in"
ENV["SYNC_API_BASE_URL_SG"] ||= "https://dev.altconnects.sg"

module IRMUtils
  def eventually(timeout: Capybara.default_max_wait_time)
    start_time = Time.now
    begin
      yield
    rescue RSpec::Expectations::ExpectationNotMetError, ActiveRecord::RecordNotFound, Capybara::ElementNotFound => e
      raise e if Time.now - start_time >= timeout
      sleep 0.5
      retry
    end
  end

  def key_values(model, args)
    puts "Setting #{args} on #{model.class} #{model.id}"
    # Limit the split to 2 so an intentionally empty value survives: "unit_type=" has to
    # parse as {"unit_type" => ""} (a commitment with no unit type), but a plain
    # split("=") drops the trailing empty field and to_h then raises ArgumentError.
    # It also lets a value contain "=" instead of blowing up on the extra field.
    key_val = args.split(";").map { |kv| kv.split("=", 2) }.to_h
    key_val.each do |k, v|
      # model[k] = v
      puts "Setting #{k} to #{v} on #{model.class} #{model.id}"
      if k == "properties"
        v.split(",").each do |prop|
          prop_key, prop_val = prop.split(":")
          model.properties[prop_key] = prop_val
          puts "Setting properties[#{prop_key}] = #{prop_val} on #{model.class} #{model.id} "
        end
      else
        model.send("#{k}=", v)
      end
    end
  end

  def hash_key_values(model, args)
    key_val = args.split(";").to_h { |kv| kv.split("=") }
    key_val.each do |k, v|
      model[k] = v
    end
  end

  # This is to scroll to the Account Entries tab and click it, otherwise the turbo_frame does not lazy load unless you scroll to it
  def click_tab(tab_name)
    tab = find('a.nav-link', text: tab_name)
    tab.scroll_to(tab)
    tab.click
  end
end

World(IRMUtils)

AfterAll do
  # Only remove this process's upload directory so parallel workers don't
  # delete files that other still-running processes depend on.
  n = ENV.fetch('TEST_ENV_NUMBER', 'test')
  FileUtils.rm_rf(Rails.root.join('public', 'uploads', n.to_s))
  FileUtils.rm_rf(Rails.root.join('public', 'uploads', 'cache', n.to_s))
end
